fns.initCropper:
function initCropper(imageElement) {
    const {
        aspectRatio,
        minCropBoxWidth,
        minCropBoxHeight,
        modalWidth,
        modalHeight,
    } = cropperSettings;

    const naturalWidth = imageElement.naturalWidth;
    const naturalHeight = imageElement.naturalHeight;
    const imageAspectRatio = naturalWidth / naturalHeight;
    const containerAspectRatio = modalWidth / modalHeight;
    let containerWidth, containerHeight;

    if (imageAspectRatio > containerAspectRatio) {
        containerWidth = modalWidth;
        containerHeight = modalWidth / imageAspectRatio;
    } else {
        containerWidth = modalHeight * imageAspectRatio;
        containerHeight = modalHeight;
    }

    if (cropper) {
        cropper.destroy();
    }

    cropper = new Cropper(imageElement, {
        aspectRatio: aspectRatio,
        viewMode: 2,
        autoCropArea: 0.8,
        movable: true,
        cropBoxResizable: true,

        minCropBoxWidth: minCropBoxWidth,
        minCropBoxHeight: minCropBoxHeight,
        minContainerWidth: modalWidth,
        minContainerHeight: modalHeight,
        ready: function () {
            this.cropper.setCanvasData({
                width: containerWidth,
                height: containerHeight,
            });
        },
    });
    return cropper;
}

fns.creatfileCrop:
async function creatfileCrop(id, filecrop, filename) {
    var app = getParameterByName("App");
    let dataTransfer = new DataTransfer();
    dataTransfer.items.add(filecrop);
    let fileList = dataTransfer.files;
    let file_list_crop = fileList[0];

    $("#file_name_" + id).prop("files", fileList);
    var objectUrl = URL.createObjectURL(fileList[0]);
    var span = $("#show_file_name_" + id);
    var sum_file = $("#file_link_file_name_" + id);

    if (app == "Y" || app == "y") {
        getBase64(file_list_crop)
            .then((base64) => {
                $("#show_file_name_" + id).html(
                    '<a onclick="sendmessage(&quot;' +
                    base64 +
                    '&quot;)"><span class="name-file">' +
                    filename +
                    "</span></a>"
                );
                $("#file_link_file_name_" + id).html(
                    '<a onclick="sendmessage(&quot;' +
                    base64 +
                    '&quot;)"><img src="/assets/images/document.svg" class="iconbook"></a>'
                );
            })
            .catch((error) => {
                console.error("Error converting file to Base64:", error);
            });
    } else {
        $("#show_file_name_" + id).html(
            '<a href="' +
            objectUrl +
            '" target="_blank"><span class="name-file">' +
            filename +
            "</span></a>"
        );
        $("#file_link_file_name_" + id).html(
            '<a href="' +
            objectUrl +
            '" target="_blank"><img src="/assets/images/document.svg" class="iconbook"></a>'
        );
    }
}

