fns.checkTypeNameSizeFile:
function checkTypeNameSizeFile(id, file,type) {
    /*var maxSizeMB = important_data.file_size;*/
    var specialFilenameChars = /["\\/:*?<>|,]/;

    var maxSizeMB;
    var classfile;

    if (type == "MT_63_2_3103_RENEWAL") {
        maxSizeMB = important_data.file_size_ticket_2;
        classfile = "lang_file_size_exceeded_2"
    } else {
        maxSizeMB = important_data.file_size;
        classfile = "lang_file_size_exceeded"
    }

    var CheckFileType_file = [
        "image/png",
        "image/jpg",
        "image/jpeg",
        "application/pdf",
    ];

    if (type == "MT_63_2_3103_RENEWAL") {
        CheckFileType_file.push(
            "application/vnd.ms-excel", // .xls
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" // .xlsx
        );
    }
    var CheckFileType_img = ["image/png", "image/jpg", "image/jpeg"];
    var checkFile_type;
    checkFile_type = id === "42" ? CheckFileType_img : CheckFileType_file;
    // Check if the file exists
    if (!file) {
        console.error("No file provided for validation.");
        return false;
    }

    // Check for invalid characters in the filename

    if (specialFilenameChars.test(file.name)) {
        Swal.fire({
            imageUrl: important_data.warningIconUrl,
            title: `<span class="lang_Invalid_file_name">ชื่อไฟล์ไม่ถูกต้อง</span>`,
            html: `<span class="lang_invalid_characters">ชื่อไฟล์มีอักขระที่ไม่ถูกต้อง</span> <span>(\\/:*?&lt;&gt;|,)</span>`,
            confirmButtonText: "<span data_th='ตกลง' data_en='OK'></span>",
        });

        changeDatalang();
        return false;
    }

    // Check if the file type is allowed
    if (!checkFile_type.includes(file.type)) {
        Swal.fire({
            imageUrl: important_data.warningIconUrl,
            title: `<span class="lang_invalid_file_type">ชนิดของไฟล์ไม่ถูกต้อง</span>`,
            confirmButtonText: "<span data_th='ตกลง' data_en='OK'></span>",
        });
        changeDatalang();
        return false;
    }

    // Check if the file size exceeds the limit
    const fileSizeMB = file.size / (1024 * 1024); // Convert bytes to MB
    if (fileSizeMB > maxSizeMB) {
        Swal.fire({
            imageUrl: important_data.warningIconUrl,
            title: `<span class="${classfile}">ขนาดของไฟล์เกิน</span>`,
            confirmButtonText: "<span data_th='ตกลง' data_en='OK'></span>",
        });
        changeDatalang();
        return false;
    }

    // If all checks pass
    return true;
}
